func fetch(work <-chan string) {
	select {
	case v := <-work:
		fmt.Println("got", v)
	case <-time.After(10 * time.Millisecond):
		fmt.Println("timed out") // wins if work is slow
	}
}

func main() {
	work := make(chan string)
	go func() {
		time.Sleep(50 * time.Millisecond) // too slow
		work <- "done"
	}()
	fetch(work)
}
